11	    let service: ModelingSubmissionService;
12	    let httpMock: HttpTestingController;
13	    let elemDefault: ModelingSubmission;
14	
15	    beforeEach(() => {
16	        TestBed.configureTestingModule({
17	            imports: [],
18	            providers: [provideHttpClient(), provideHttpClientTesting(), { provide: AccountService, useClass: MockAccountService }],
19	        });
20	        service = TestBed.inject(ModelingSubmissionService);
21	        httpMock = TestBed.inject(HttpTestingController);
22	
23	        elemDefault = new ModelingSubmission();
24	        elemDefault.id = 5;
25	    });
26	
27	    const getDefaultValues = (updateValues = {}) => {
28	        const exerciseId = 5;
29	        const returnedFromService = { ...elemDefault, id: exerciseId, ...updateValues };
30	        const expected = { ...returnedFromService };
31	        const requestOption = { test: 'Test' };
32	        const correctionRound = 7;
33	        const participationId = 4;
34	        return { exerciseId, returnedFromService, expected, requestOption, correctionRound, participationId };
35	    };
36	
37	    it('should find an element', fakeAsync(() => {
38	        const { returnedFromService, correctionRound } = getDefaultValues();
39	        service
40	            .getSubmission(123, correctionRound)
41	            .pipe(take(1))
42	            .subscribe((resp) => expect(resp).toEqual({ ...elemDefault }));
43	
44	        const req = httpMock.expectOne({ method: 'GET', url: `api/modeling-submissions/123?correction-round=7` });
45	        expect(req.request.params.get('correction-round')).toBe(`${correctionRound}`);
46	        req.flush(returnedFromService);
47	        tick();
48	    }));
49	
50	    it('should create a ModelingSubmission', fakeAsync(() => {
51	        const { returnedFromService, expected } = getDefaultValues();
52	        service
53	            .create(new ModelingSubmission(), 1)
54	            .pipe(take(1))
55	            .subscribe((resp) => expect(resp).toMatchObject({ body: expected }));
56	        const req = httpMock.expectOne({ method: 'POST' });
57	        req.flush(returnedFromService);
58	        tick();
59	    }));
60	
61	    it('should update a ModelingSubmission', fakeAsync(() => {
62	        const { returnedFromService, expected } = getDefaultValues({ model: 'BBBBBB', explanationText: 'BBBBBB' });
63	        service
64	            .update(expected, 1)
65	            .pipe(take(1))
66	            .subscribe((resp) => expect(resp).toMatchObject({ body: expected }));
67	        const req = httpMock.expectOne({ method: 'PUT' });
68	        req.flush(returnedFromService);
69	        tick();
70	    }));
71	
72	    it('should get submissions without correction round', fakeAsync(() => {
73	        const { exerciseId, returnedFromService, requestOption } = getDefaultValues();
74	        service
75	            .getSubmissions(exerciseId, requestOption)
76	            .pipe(take(1))
77	            .subscribe((resp) => expect(resp).toMatchObject({ body: [] }));
78	        const req = httpMock.expectOne({ method: 'GET', url: `${service.resourceUrl}/exercises/${exerciseId}/modeling-submissions?test=Test` });
79	        expect(req.request.params.get('test')).toBe('Test');
80	        req.flush(returnedFromService);
81	        tick();
82	    }));
83	
84	    it('should get submissions with correction round', fakeAsync(() => {
85	        const { exerciseId, returnedFromService, requestOption, correctionRound } = getDefaultValues();
86	        service
87	            .getSubmissions(5, requestOption, correctionRound)
88	            .pipe(take(1))
89	            .subscribe((resp) => expect(resp).toMatchObject({ body: [] }));
90	        const req = httpMock.expectOne({ method: 'GET', url: `${service.resourceUrl}/exercises/${exerciseId}/modeling-submissions?test=Test&correction-round=${correctionRound}` });
91	        expect(req.request.params.get('test')).toBe('Test');
92	        expect(req.request.params.get('correction-round')).toBe(`${correctionRound}`);
93	        req.flush(returnedFromService);
94	        tick();
95	    }));
96	
