98	        const { exerciseId, returnedFromService, correctionRound } = getDefaultValues();
99	        service
100	            .getSubmissionWithoutAssessment(exerciseId, true, correctionRound)
101	            .pipe(take(1))
102	            .subscribe((resp) => expect(resp).toStrictEqual({ ...elemDefault }));
103	        const req = httpMock.expectOne({ method: 'GET', url: `api/exercises/${exerciseId}/modeling-submission-without-assessment?correction-round=${correctionRound}&lock=true` });
104	        expect(req.request.params.get('lock')).toBe('true');
105	        expect(req.request.params.get('correction-round')).toBe(`${correctionRound}`);
