111	        const { returnedFromService, participationId } = getDefaultValues();
112	        service
113	            .getLatestSubmissionForModelingEditor(participationId)
114	            .pipe(take(1))
115	            .subscribe((resp) => expect(resp).toMatchObject({ ...elemDefault }));
116	        const req = httpMock.expectOne({ method: 'GET', url: `api/participations/${participationId}/latest-modeling-submission` });
117	        req.flush(returnedFromService);
