     * Builds the sorted submission and result history used by the feedback view so that the student can browse
     * their past submissions and the feedback for a specific one.
     * The submissions are sorted by the completion date of their latest result in descending order, and one result
     * per submission (its latest result) is kept in the same order.
     * @param submissions the submissions with their results for the participation
     */
    private updateSubmissionHistory(submissions: ModelingSubmission[]): void {
        const completionDate = (submission: ModelingSubmission) => getLatestSubmissionResult(submission)?.completionDate;
        this.sortedSubmissionHistory = [...submissions].sort((a, b) => {
            const aDate = completionDate(a);
            const bDate = completionDate(b);
            if (!aDate) {
                return 1;
            }
            if (!bDate) {
                return -1;
            }
            return dayjs(bDate).valueOf() - dayjs(aDate).valueOf();
        });
        this.sortedResultHistory = this.sortedSubmissionHistory
            .map((submission) => getLatestSubmissionResult(submission))
            .filter((result): result is Result => result != undefined);
    }

